C = (A - D - D)/(H*H)
DX = XX - X(I)
YI(K) = Y(I) + DX*(YP(I) + DX*(B + DX*C))
B = B + B
C = 3.0*C
YPI(K) = YP(I) + DX*(B + DX*C)
YPPI(K) = B + DX*(C + C)
!
